\section{Theory Critique}


%-SLIDE-08 Is $\theoryblue{\text{MSE}_{\ast}^{UB}}$ general?
\begin{frame}{Comment: Is $\theoryblue{\text{MSE}_{\ast}^{UB}}$ general?}
    \begin{itemize}
        \item The \blue{beautiful closed-form estimator:}
              \[
                  \theoryblue{\text{MSE}_{\ast}^{UB}}
                  \equiv
                  \frac{
                      \theorygreen{\text{MSE}_{OOS}}
                  }{
                      1+
                      \theoryblue{T_{OOS}^{-1}\,
                          \text{tr}
                          \left(
                          \hat{\mathcal{K}}^{\prime}
                          \hat{\mathcal{K}}
                          \right)}
                  }
                  =
                  \frac{
                      \theorygreen{\text{MSE}_{OOS}}
                  }{
                      1+
                      \theoryblue{T_{OOS}^{-1}\,
                          \text{tr}\!
                          \left(
                          \left[
                              \frac{\partial\hat{f}_{OOS}}{\partial\varepsilon_{IS}}
                              \right]^{\prime}
                          \left[
                              \frac{\partial\hat{f}_{OOS}}{\partial\varepsilon_{IS}}
                              \right]
                          \right)}
                  }
              \]
        \item Depends on the forecasting function $\hat{f}_{OOS}$
              \begin{align*}
                  \theoryblue{\text{MSE}_{\ast,\text{OLS}}^{UB}}
                   & \ne
                  \theoryblue{\text{MSE}_{\ast,\text{RFF-Ridge}(P)}^{UB}}
                  \ne
                  \theoryblue{\text{MSE}_{\ast,\text{RFF-Ridge}(P')}^{UB}}
              \end{align*}
              Equivalently,
              \begin{align*}
                  \theoryblue{R_{\ast,LB,\text{OLS}}^{2}}
                   & \ne
                  \theoryblue{R_{\ast,LB,\text{RFF-Ridge}(P)}^{2}}
                  \ne
                  \theoryblue{R_{\ast,LB,\text{RFF-Ridge}(P')}^{2}}
              \end{align*}

        \item \red{Is this a ``fully data-driven lower bound'' }
        \item \red{Does it ``depends only on the observed sample''?}
    \end{itemize}
\end{frame}


